import{_ as o}from"./chunks/architecture.Cs8uKTTN.js";import{_ as r,o as a,c,a2 as d}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"アーキテクチャ","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/dev-guide/architecture.md","filePath":"ja-JP/dev-guide/architecture.md","lastUpdated":1785993908000}'),t={name:"ja-JP/dev-guide/architecture.md"};function i(l,e,p,s,n,h){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="アーキテクチャ" tabindex="-1">アーキテクチャ <a class="header-anchor" href="#アーキテクチャ" aria-label="Permalink to &quot;アーキテクチャ&quot;">​</a></h1><p><img src="'+o+'" alt="Lertaro のアーキテクチャ"></p><h2 id="プロセスの分割" tabindex="-1">プロセスの分割 <a class="header-anchor" href="#プロセスの分割" aria-label="Permalink to &quot;プロセスの分割&quot;">​</a></h2><p>Lertaro は、権限レベルとライフタイムに応じて意図的に分離された3つの独立したプロセスとして動作します。</p><ul><li><strong><code>Lertaro.Service</code></strong> — <code>LocalSystem</code> として動作する Windows サービスです。ファイルインデックス作成のすべてを担当します。NTFS/ReFS ドライブの USN Journal と MFT の読み取り、ジャーナルを持たない他のローカルファイルシステムの直接的な走査と監視、ネットワーク共有のスキャンとキャッシュ、そして名前付きパイプ経由での検索クエリへの応答です。SYSTEM レベルで動作させることで、どのユーザーアカウントからも参照可能な生のボリュームメタデータを読み取れるようになり、対話型の App プロセスに不要な昇格権限を与えずに済みます。</li><li><strong><code>Lertaro.App</code></strong> — ユーザーごと、セッションレベルで動作する WPF アプリケーションです。検索ウィンドウ、設定ウィンドウ、ホットキー処理、アクションメニュー/QuickLook UI を担います。Service とは名前付きパイプ(<code>Core.Services</code> の <code>SearchService</code>/<code>UsnServicePipeServer</code>)経由でやり取りし、ディスクインデックスに直接触れることはありません。また、App 自身もユーザーごとの2つ目のパイプ (<code>AppSearchPipeService</code>)をホストしており、これにより <code>lff</code> CLI コンパニオン(<a href="./../user-guide/cli.html">コマンドライン検索</a>を参照)は、素の状態から独自にセットアップをやり直すのではなく、App がすでに初期化済みの検索状態 ——読み込み済みのエイリアス/プラグインプロバイダー、設定済みのネットワークドライブインデックス—— を再利用できます。</li><li><strong><code>Lertaro.Service --hook</code></strong> — 低レベルのグローバルキーボードフックだけをホストする、独立した小さなプロセスです。フックのクラッシュや不安定なフォアグラウンドアプリが、メインの App プロセスを巻き添えにしないようにするためです。またこのプロセスは、プラグインのウィンドウ統合アダプターも読み込み、その呼び出し自体を自分自身の中で実行します。詳しくは下記の<a href="#プラグインの位置づけ">プラグインの位置づけ</a>を参照してください。</li></ul><h2 id="共有される-core" tabindex="-1">共有される Core <a class="header-anchor" href="#共有される-core" aria-label="Permalink to &quot;共有される Core&quot;">​</a></h2><p><code>Core</code> は Service と App の両方から参照されるクラスライブラリです。次のものを保持しています。</p><ul><li>検索エンジン(<code>Core/SearchIndex/Fzf/*</code>) — <code>fzf</code> コマンドラインツールのアルゴリズムをモデルにしたあいまい検索の実装で、ドライブレター指定やパスモード検索のためのクエリパーサー(<code>SearchQueryParser</code>) も含みます。</li><li>ランタイムインデックス(<code>Core/IndexV2/*</code>) — USN/MFT の読み取りから構築される、メモリマップ方式の列指向スナップショット形式で、最後のスナップショット以降の変更を保持するメモリ内デルタオーバーレイを備えています。</li><li>IPC コントラクト(<code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> など) — App と Service の両方でそのまま共有され、両プロセスが常に同じワイヤーフォーマットに合意していることを保証します。</li><li><code>Logger</code> — プロセスごとのログファイル(<code>service.log</code>、<code>app.log</code>、<code>hook.log</code>)に書き込みます。これらはすべて App の 設定 → サービスの状態 のログビューアーから読み取り可能です(ただし、すべてが書き込み可能というわけではありません)。</li></ul><h2 id="プラグインの位置づけ" tabindex="-1">プラグインの位置づけ <a class="header-anchor" href="#プラグインの位置づけ" aria-label="Permalink to &quot;プラグインの位置づけ&quot;">​</a></h2><p>プラグインは <code>PluginSdk</code> を参照する <code>.dll</code> アセンブリであり、App プロセスによって読み込まれます (<a href="./getting-started.html">はじめに</a>と<a href="./packaging.html">パッケージングと配布</a>を参照)。Lertaro 自身にも、第一級のサンプルとして2つのプラグインが同梱されています——<code>Lertaro.Plugins.CoreExtensions</code>(組み込みのファイル操作とシェルのコンテキストメニュー統合)と <code>Lertaro.Plugins.PinyinAlias</code>(中国語ファイル名向けのピンインエイリアス)です。両者の詳しい解説は<a href="./examples.html">サンプルプラグイン</a>を参照してください。</p><p>プラグインが Service と直接やり取りすることはありません。プラグインはプラグイン SDK リファレンスに記載されているインターフェースを通じて App とやり取りし、(カスタムのインデックス対象ディレクトリが必要な場合の)ディスクインデックスとのやり取りは、代わりに Service へプロキシする <code>DirectoryIndexerService</code> を通じて行います。</p><p>ウィンドウ統合アダプターは、「App だけで完結する」という原則の唯一の例外です。 <a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code></a> の実装は Hook プロセスにも二重に読み込まれ、その呼び出しは App ではなく Hook プロセス側で実行されます。これにより、App 自体は常に非昇格で動作しているにもかかわらず、Lertaro は昇格した File Explorer/ファイルダイアログ/サードパーティ製ファイルマネージャーのウィンドウを操作できます——Windows は低権限プロセスから高権限プロセスへの入力送信をブロックするため、呼び出しは対象と同じ権限レベルで動作するプロセスから発行される必要があるからです。</p>',12)])])}const m=r(t,[["render",i]]);export{g as __pageData,m as default};
